import Foundation
import Foundation

/// Верхний внешний зазор включает промежуток между полем ввода и панелью.
struct NagramiXFormattingBands {
    let top: CGFloat
    let bottom: CGFloat

    static func layout(composerGap: CGFloat, safeBottom: CGFloat, landscape: Bool,
                       referenceLineHeight: CGFloat) -> NagramiXFormattingBands {
        let gap = composerGap.isFinite ? max(0, composerGap) : 0
        let safe = safeBottom.isFinite ? max(0, safeBottom) : 0
        let line = referenceLineHeight.isFinite ? max(0, referenceLineHeight) : 0
        // Сохраняем компактный размер прежней полосы, независимо от текста UILabel.
        let outside = max(ceil(line) + (landscape ? 12 : 16), safe + 8, gap + 8)
        return NagramiXFormattingBands(top: outside - gap, bottom: outside)
    }
}
